claims.text:
body{font:14px/1.7 system-ui,"Microsoft YaHei",sans-serif;background:#0b1020;color:#e7ecff;margin:0}
main{max-width:1100px;margin:auto;padding:24px}
h1{font-size:20px;line-height:1.5}
h2{font-size:17px;border-left:4px solid #4d7cff;padding-left:10px;margin:26px 0 10px}
.hint{color:#a9b7d5}
.card{border:1px solid #34405e;border-radius:12px;padding:16px 18px;margin:12px 0;background:#111a2e}
.kpi{display:inline-block;border:1px solid #3d4f78;border-radius:10px;padding:8px 14px;margin:4px 8px 4px 0;background:#0e1730}
.kpi b{font-size:18px;color:#8fb8ff;margin-right:6px}
.trow{border-top:1px solid #26314d;padding:10px 0}
.tr1{font-weight:700}
.tnm{color:#e7ecff;margin-right:10px}
.tjd{color:#8fb8ff;margin-right:10px}
.tct{color:#a9b7d5;font-size:12px}
.tds{color:#b9c6e2;margin-top:4px}
.obslist{display:grid;gap:12px}
.obs{border:1px solid #3d4f78;border-radius:10px;padding:12px;background:#0e1730}
.obs-head{display:flex;gap:10px;align-items:baseline}
.obs-nm{font-weight:700;font-size:16px}
.obs-pos{margin-left:auto;color:#ffd479}
.obs-lab,.obs-lab2{color:#8fb8ff;font-weight:600}
.obs-watch,.obs-rec{margin-top:6px}
.mut{color:#a9b7d5}
.sup{font-size:12px;color:#a9b7d5}
.tl{border-left:2px solid #3d4f78;margin:8px 0 8px 6px;padding-left:14px}
.tli{margin:10px 0}
table{border-collapse:collapse;width:100%;margin:8px 0}
th,td{border:1px solid #34405e;padding:5px 8px;text-align:left;font-size:13px}
th{background:#16203a;color:#cfe0ff}
code{color:#a7d8ff}
